-- The SELF-GRIP code key (Code keys -> Parting -> SELF-GRIP), from the ISCAR
-- e-catalog's SELF-GRIP families (inserts GFN / GFR / GFL / GFF and their
-- blades and tools); kept if one exists. "(inferred)" marks meanings read off
-- the designations.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.selfgrip', $ck${"title": "SELF-GRIP code key – inserts and tools", "subtitle": "Self-clamped single-ended inserts (GFN / GFR / GFL, GFF for face grooving) and their blades and tools", "example": "GFR 3JS-8D", "decoder": "self-grip", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "GF", "rows": [{"code": "GF", "meaning": "SELF-GRIP single-ended insert (GFN / GFR / GFL)"}, {"code": "GFF", "meaning": "SELF-GRIP face grooving insert (GFF 3N / 3R / 3L)"}]}, {"key": "i-hand", "title": "Hand of insert", "rows": [{"code": "N", "meaning": "Neutral"}, {"code": "R", "meaning": "Right"}, {"code": "L", "meaning": "Left"}], "sample": "R"}, {"key": "i-width", "title": "Insert – cutting width", "sample": "3", "rows": [{"code": "#", "meaning": "Cutting width in mm (e.g. 3, 1.6, 4.8)"}]}, {"key": "i-chip", "title": "Chipformer", "sample": "J", "rows": [{"code": "(none)", "meaning": "C type – parting bars, hard materials and tough applications (no letter, e.g. GFN 3)"}, {"code": "J", "meaning": "Soft materials, parting of tubes, small diameters and thin-walled parts"}, {"code": "W", "meaning": "Central ridged chipformer for steel (and stainless steel)"}, {"code": "M", "meaning": "Parting nonferrous bars"}, {"code": "A", "meaning": "Parting aluminum"}, {"code": "U", "meaning": "Low feeds on Cr-Ni alloys and low carbon steel"}, {"code": "B", "meaning": "C type variant B (GFN-C family) (inferred)"}, {"code": "E", "meaning": "C type variant E (GFN-C family) (inferred)"}]}, {"key": "i-sharp", "title": "Sharp corners (optional)", "sample": "S", "rows": [{"code": "S", "meaning": "Sharp corners (e.g. GFN 3JS, GFR 2S-8D)"}]}, {"key": "i-lead", "title": "Lead angle", "rows": [{"code": "#D", "meaning": "Lead angle in degrees (e.g. 6D = 6°)"}, {"code": "##D", "meaning": "Lead angle in degrees (e.g. 15D = 15°)"}], "sample": "8D"}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "SGFH", "meaning": "Blades with and without coolant holes (SGFH, SGFHR/L, four-pocket SGFH 100/150, F-type SGFHR/L-26T/32T)"}, {"code": "SGFS", "meaning": "Replacement blades for HSS and brazed parting tools"}, {"code": "SGTF", "meaning": "Integral shank tools (SGTFR / SGTFL, -D reinforced)"}, {"code": "SGAF", "meaning": "Integral shank tools for Swiss automatic machines (SGAFR / SGAFL)"}, {"code": "SGB", "meaning": "Single-sided blades"}, {"code": "SGF", "meaning": "Integral shank short head tools for CNC and Swiss automatics (SGFR/L-B-D-SH)"}, {"code": "SGFFA", "meaning": "Reinforced face grooving blades for standard tool blocks"}, {"code": "SGFFH", "meaning": "Face grooving blades"}, {"code": "SGFF", "meaning": "Face grooving integral shank tools (SGFFR / SGFFL)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}, {"code": "R/L", "meaning": "Right- or left-hand"}, {"code": "N", "meaning": "Neutral"}, {"code": "RE", "meaning": "Right-hand, E type (RE/LE adapters) (inferred)"}, {"code": "LE", "meaning": "Left-hand, E type (RE/LE adapters) (inferred)"}, {"code": "R/LE", "meaning": "Right- or left-hand, E type (inferred)"}]}, {"key": "t-angle", "title": "Tool – angle a° (multi-spindle blades)", "rows": [{"code": "#", "meaning": "Angle a° (0 or 5)"}]}, {"key": "t-height", "title": "Tool – blade height / shank", "rows": [{"code": "##", "meaning": "Blade height or shank size in mm (e.g. 26, 32)"}, {"code": "###", "meaning": "Blade height in mm (e.g. 100, 150)"}, {"code": "####", "meaning": "Shank height x width in mm (e.g. 2525 = 25 x 25)"}]}, {"key": "t-width", "title": "Tool – insert width (seat)", "rows": [{"code": "#", "meaning": "Insert width in mm (the seat's insert, e.g. 3)"}]}, {"key": "t-dia", "title": "Tool – D size", "rows": [{"code": "D##", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D24, D52) (inferred)"}, {"code": "D###", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D120) (inferred)"}]}, {"key": "t-pockets", "title": "Tool – pockets", "rows": [{"code": "#Z", "meaning": "Number of pockets (e.g. 2Z, 4Z)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "JHP", "meaning": "Channels for high-pressure coolant"}, {"code": "MC", "meaning": "Bottom inlets for the high-pressure coolant"}, {"code": "K", "meaning": "With coolant holes (10 bar min.; cooling tube SGCU 341 ordered separately)"}, {"code": "C", "meaning": "With coolant – frontal coolant holes (JETCUT) / internal coolant"}, {"code": "XL", "meaning": "Extra long"}, {"code": "SH", "meaning": "Short head (CNC and Swiss automatics)"}, {"code": "S", "meaning": "Single-sided blade (e.g. TGFH-S) / for next to high shoulders (e.g. PCHRS)"}, {"code": "IQ", "meaning": "IQ line (e.g. TGTR/L-IQ, PCHR/L-D-IQ)"}, {"code": "TR", "meaning": "For TRAUB and Index machines"}, {"code": "MB", "meaning": "For other manufacturers' blocks"}, {"code": "B", "meaning": "B type, e.g. DGTR/L-B-D (reinforced) / DGAD-B-D (screw-clamped) (inferred)"}, {"code": "L###", "meaning": "Tool length in mm (e.g. L120)"}, {"code": "T##", "meaning": "F-type reinforced blade, T size (e.g. 26 T 16) (inferred)"}]}, {"key": "t-dmin", "title": "Tool – face grooving diameter", "rows": [{"code": "##", "meaning": "Minimum face grooving diameter in mm (e.g. 35) (inferred)"}, {"code": "###", "meaning": "Minimum face grooving diameter in mm (e.g. 100) (inferred)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
